  assert(notes.isSelfNotes === true && storedNotes.messages.some((message) => message.content.text === marker('note')), 'Notes to self were not persistent.');
  assert(reopened._id === group._id && renamed.name === 'Sanity group renamed' && renamed.members.length === 3, 'Group DM did not preserve membership or rename.');
});

    await scenario('direct-and-group-conversations-05', async () => {
      const sourceMessage = await send(dm._id, people.A.token, marker('expansion-source'));
      const none = expectSuccess(await request(`/api/channels/${dm._id}/expand`, { method: 'POST', token: [REDACTED], body: { userIds: [people.B.userId], history: 'none' } }), 'expand without history').channel;
      const all = expectSuccess(await request(`/api/channels/${dm._id}/expand`, { method: 'POST', token: [REDACTED], body: { userIds: [people.C.userId], history: 'all' } }), 'expand with history').channel;
      const [noneMessages, allMessages, sourceMessages] = await Promise.all([
        request(`/api/channels/${none._id}/messages`, { token: [REDACTED] }), request(`/api/channels/${all._id}/messages`, { token: [REDACTED] }), request(`/api/channels/${dm._id}/messages`, { token: [REDACTED] }),
